test_suite:
test('initial state is returned correctly', () => {
  const { result } = renderHook(() =>
    useAsyncReducer((s: number, _: any) => s, 42)
  );
  expect(result.current[0]).toBe(42);
});

test('isPending starts as false', () => {
  const { result } = renderHook(() =>
    useAsyncReducer((s: number, _: any) => s, 0)
  );
  expect(result.current[2]).toBe(false);
});

test('synchronous action updates state immediately', async () => {
  const { result } = renderHook(() =>
    useAsyncReducer(
      (s: number, a: { type: string }) => a.type === 'INC' ? s + 1 : s,
      0
    )
  );
  await act(async () => result.current[1]({ type: 'INC' }));
  expect(result.current[0]).toBe(1);
});

test('async action sets isPending=true then resolves', async () => {
  let resolve!: (v: number) => void;
  const asyncReducer = (_s: number, _a: any): Promise<number> =>
    new Promise(r => { resolve = r; });
  const { result } = renderHook(() => useAsyncReducer(asyncReducer, 0));
  act(() => { result.current[1]({}); });
  expect(result.current[2]).toBe(true);
  await act(async () => resolve(99));
  expect(result.current[0]).toBe(99);
  expect(result.current[2]).toBe(false);
});

