test('multiple sync dispatches accumulate correctly', async () => {
  const { result } = renderHook(() =>
    useAsyncReducer(
      (s: number, a: { type: string }) => a.type === 'ADD' ? s + 1 : s,
      0
    )
  );
  await act(async () => { result.current[1]({ type: 'ADD' }); });
  await act(async () => { result.current[1]({ type: 'ADD' }); });
  await act(async () => { result.current[1]({ type: 'ADD' }); });
  expect(result.current[0]).toBe(3);
});

solution:
import { useState, useCallback, useRef } from 'react';

export function useAsyncReducer<S, A>(
  reducer: (state: S, action: A) => S | Promise<S>,
  initialState: S
): [S, (action: A) => void, boolean] {
  const [state, setState] = useState<S>(initialState);
  const [isPending, setIsPending] = useState(false);
  const stateRef = useRef(state);
  stateRef.current = state;

  const dispatch = useCallback(async (action: A) => {
    const result = reducer(stateRef.current, action);
    if (result instanceof Promise) {
      setIsPending(true);
      try {
        const next = await result;
        setState(next);
        stateRef.current = next;
      } finally {
        setIsPending(false);
      }
    } else {
      setState(result);
      stateRef.current = result;
    }
  }, [reducer]);

  return [state, dispatch, isPending];
}
